import { ChatComposer } from "march/ui"

// ayna: ne yazarsan büyük harflerle ve tersinden geri gelir; düğme mor, gönder ikonu bir yıldız
export function EmojiMirror() {
  let $last = "🪞 Bir şey yaz, ayna geri söylesin"
  return <div sx={{ flex: "col", gap: 2 }}>
    <p sx={{ text: ["xl", "center"], color: "brand-purple" }}>{$last}</p>
    <ChatComposer placeholder="Aynaya yaz" sendColor="brand-purple" sendIcon="✨"
      onSend={(text) => $last = [...text.toLocaleUpperCase("tr-TR")].reverse().join("")} />
  </div>
}

import { ChatComposer, toast } from "march/ui"
import { image, fileText, mapPin } from "march/icons"

// bir ekip sohbetinin yazma kutusu: metin ya da sesli mesaj gönderir, ek menüsünden fotoğraf / dosya / konum seçilir,
// yazarken "yazıyor…" sinyali gider; gönderilenler üstte listelenir
export function TeamMessage() {
  let $sent: string[] = []
  let $typing = ""
  const add = (s: string) => { $sent = [...$sent.slice(-3), s]; $typing = "" }
  return <div sx={{ flex: "col", gap: 2 }}>
    <ul sx={{ flex: "col", gap: 1 }}>{$sent.length ? $sent.map((s) => <li>{s}</li>) : <li sx={{ color: "muted" }}>Henüz mesaj yok</li>}</ul>
    <span sx={{ text: "xs", color: "muted" }}>{$typing}</span>
    <ChatComposer placeholder="#tasarım kanalına yaz"
      onSend={(text) => add(`💬 ${text}`)}
      onVoice={(ms) => add(`🎤 Sesli mesaj · ${(ms / 1000).toFixed(1)} sn`)}
      onTyping={() => $typing = "Ekibe: yazıyor…"}
      attachments={[
        { label: "Fotoğraf", icon: image, onSelect: () => add("🖼️ Fotoğraf eklendi") },
        { label: "Dosya", icon: fileText, onSelect: () => add("📄 Dosya eklendi") },
        { label: "Konum", icon: mapPin, onSelect: () => toast("Konum izni istenir") },
      ]} />
  </div>
}

import { ChatComposer, Button, Badge, Card } from "march/ui"
import { image, send, mic, heart, plus } from "march/icons"

// ChatComposer'ın bütün özellikleri: gönder, sesli mesaj, ek menüsü, emoji düğmesi, yanıt satırı (kapatılabilir),
// yazıyor sinyali, yer tutucu, kapalı durum, kendi metinler, kendi ikonlar, düğme renkleri, dalga ve kayıt noktası,
// hareket ve sınıf; koyu zeminde
export function ChatComposerLab() {
  let $log = "-"
  let $typing = 0
  let $reply: { name: string; text: string } | null = { name: "Ece", text: "Yarın kaçta buluşuyoruz?" }
  let $off = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button size="sm" variant="ghost" on:click={() => $off = !$off}>{$off ? "Aç" : "Kapat"}</Button>
      <Button size="sm" variant="ghost" on:click={() => $reply = { name: "Can", text: "Ben de geliyorum" }}>Can'a yanıt ver</Button>
      <Badge tone="primary">{$log}</Badge>
      <span sx={{ text: "xs", color: "muted" }}>{`yazıyor sinyali: ${$typing}`}</span>
    </div>
    <Card m:theme="night">
      <ChatComposer class="lab-composer" placeholder={() => ($off ? "Sohbet kapalı" : "Bir mesaj yaz")} disabled={() => $off}
        onSend={(text) => { $log = `gönderildi: ${text}`; $reply = null }}
        onVoice={(ms) => $log = `ses: ${ms} ms`} onTyping={() => $typing++}
        attachments={[{ label: "Fotoğraf", icon: image, onSelect: () => $log = "ek: fotoğraf" }]}
        emoji={true} replyTo={() => $reply} onCancelReply={() => $reply = null}
        labels={{ message: "Mesaj kutusu", emoji: "Emoji seç", attach: "Ekle", send: "Yolla", record: "Kaydet", sendVoice: "Sesi yolla",
          cancelRecording: "Kaydı at", cancelReply: "Yanıtı kapat", recording: "Kaydediliyor", replyingTo: (n) => `${n} kişisine yanıt` }}
        attachIcon={plus} emojiIcon={heart} sendIcon={send} micIcon={mic} sendColor="brand-green" micColor="brand-pink"
        wave={false} recordingDot={false} motion={false} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ChatComposerLab } from "./ChatComposerLab.tsx"

// ChatComposerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("yazıp Enter'a basınca onSend metni alır, yanıt satırı kapanır", async () => {
  const s = renderTest(() => <ChatComposerLab />)
  const box = await s.type("Mesaj kutusu", "Saat yedide")
  await s.press("Enter", box)
  await s.wait(() => s.sees("gönderildi: Saat yedide"))
  expect(s.sees("gönderildi: Saat yedide")).toBe(true)
  expect(s.sees("Ece kişisine yanıt")).toBe(false)
})

test("yazarken onTyping sinyali gider", async () => {
  const s = renderTest(() => <ChatComposerLab />)
  await s.type("Mesaj kutusu", "m")
  expect(s.sees("yazıyor sinyali: 1")).toBe(true)
})

test("yanıt satırı kendi metniyle görünür; kapatma düğmesi onCancelReply'ı çalıştırır", async () => {
  const s = renderTest(() => <ChatComposerLab />)
  expect(s.sees("Ece kişisine yanıt")).toBe(true)
  await s.click("Yanıtı kapat")
  expect(s.sees("Ece kişisine yanıt")).toBe(false)
})

test("disabled: kutu yazılamaz olur, yer tutucu değişir", async () => {
  const s = renderTest(() => <ChatComposerLab />)
  await s.click("Kapat")
  const box = s.find("Mesaj kutusu") as HTMLTextAreaElement | null
  expect(box?.getAttribute("placeholder")).toBe("Sohbet kapalı")
  expect(!!box?.disabled || box?.getAttribute("readonly") != null || box?.getAttribute("disabled") != null).toBe(true)
})
